  const result = await page.evaluate((text) => {
    const view = document.querySelector('.cm-content')?.cmView?.view;
    if (!view) return { ok: false, error: 'no CodeMirror view' };
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: text } });
    const doc = view.state.doc.toString();
    const idx = doc.indexOf('The main contributions are:');
    return {
      ok: true,
      len: doc.length,
      hasMakebox: doc.includes('\\\\makebox[1.6em][l]{\\\\textemdash{}}We formulate'),
      hasOld: doc.includes('\\\\textemdash{} We formulate') || doc.includes('hangafter=1 -- We formulate'),
      excerpt: idx >= 0 ? doc.slice(idx, idx + 750) : doc.slice(0, 200)
    };
  }, tex);
  return { fileLen: tex.length, result };
